powerpagecomponent.searchcontent:
Projects{% assign supplier = false %}{% if user %}{% for r in user.roles %}{% if r == 'Supplier' %}{% assign supplier = true %}{% endif %}{% endfor %}{% endif %}
{% if supplier == false %}
<div class="container py-5"><div class="alert alert-warning">This area is reserved to suppliers. <a href="/SignIn?returnUrl={{ request.path_and_query | escape }}">Sign in</a> with the account your customer invited.</div></div>
{% else %}
{% include 'OP365 Supplier Style' %}
<div class="op-shell">
{% include 'OP365 Supplier Nav' active: 'projects' %}
<main class="op-main" id="op-main">
<div class="op-head"><div><div class="op-crumb"><a href="/dashboard/">Dashboard</a> / Projects</div>
  <h1 class="op-h1">Projects</h1></div></div>
<p class="op-muted">The projects of your purchase orders: progress of the project and of your deliveries.</p>
{% include 'OP365 Supplier Project Cards' limit: 1000 %}
</main>
</div>
{% endif %}
Projects
